
#' Plot Two-Way Sensitivity Analysis Heatmaps
#'
#' Produces heatmaps from deterministic two-way sensitivity analysis
#' results generated by compute_twsa().
#'
#' Supports multiple datasets, comparisons, parameter pairs,
#' subgroups, willingness-to-pay thresholds, faceting and
#' independent plots.
#'
#' Automatically adapts to the grid resolution used in compute_twsa().
#' Three-level analyses use categorical scenario axes, while higher
#' resolutions use the actual numerical parameter values.
#'
#' @param data An object of class "twsa_result".
#' @param metric Economic outcome: "nmb", "icer",
#'   "delta_cost" or "delta_effect".
#' @param lambda Optional willingness-to-pay threshold for NMB.
#' @param impact_mode Either "absolute" (default) or "relative".
#'   Relative values represent changes from the corresponding
#'   baseline-baseline combination.
#' @param facet_by Faceting directive: "none", "dataset",
#'   "comparison", "pair", "subgroup", "subgroup_var"
#'   or "subgroup_level". NULL defaults to "pair" in Overall
#'   mode and "subgroup" in Subgroups mode.
#' @param plot_by Independent plot grouping: "none", "dataset",
#'   "comparison", "pair", "subgroup_var" or "subgroup_level".
#'   NULL defaults to "pair".
#' @param mode Either "Overall" or "Subgroups".
#' @param filter_expr Optional filtering expression.
#' @param facet_scales Facet scaling behaviour.
#' @param palette Two colours defining the continuous scale,
#'   from the lowest to the highest plotted value.
#' @param midpoint Optional midpoint for a diverging scale.
#' @param midpoint_color Colour at the midpoint.
#' @param show_values Display numeric values inside cells.
#' @param digits Number of decimal places.
#' @param return_data Return prepared plotting data.
#'
#' @details
#' For conventional three-level TWSA, the heatmap displays the
#' lower, baseline and upper scenarios as categorical axes.
#'
#' For higher resolutions, the axes represent the actual numerical
#' values of the parameters. Cell boundaries are constructed from
#' the midpoints between consecutive parameter values.
#'
#' In relative mode, each result is expressed as:
#'
#'   relative impact = scenario value - baseline value
#'
#' The baseline corresponds to the combination in which both
#' parameters take their baseline values, within the same dataset,
#' comparison, subgroup and parameter pair.
#'
#' Original economic values are preserved in the returned data.
#'
#' By default, independent plots are generated for each parameter
#' pair to prevent incompatible parameter scales from sharing axes.
#'
#' When multiple parameter pairs share a numerical plotting panel,
#' their axis identities must be compatible. Otherwise, plotting
#' stops with an informative error.
#'
#' Colours represent the magnitude of the selected plotted value,
#' not the deterministic scenario or its economic desirability.
#'
#' @return A ggplot object, a cea_multplots collection,
#'   or prepared plotting data.
#'
#' @export
#' @rawNamespace export(plot.heatmap)
plot.heatmap <- function(
    data,
    metric = "nmb",
    lambda = NULL,
    impact_mode = "absolute",
    facet_by = NULL,
    plot_by = NULL,
    mode = "Overall",
    filter_expr = NULL,
    facet_scales = "fixed",
    palette = c(
      lower = "#C0504D",
      upper = "#4472C4"
    ),
    midpoint = NULL,
    midpoint_color = "#FFFFFF",
    show_values = TRUE,
    digits = 2,
    return_data = FALSE
) {

  `%||%` <- function(a, b) {
    if (!is.null(a)) a else b
  }

  # -------------------------------------------------------------------------
  # 1. Input validation
  # -------------------------------------------------------------------------

  if (!inherits(data, "twsa_result")) {
    stop("'data' must be a twsa_result object.")
  }

  metric <- match.arg(
    metric,
    c("icer", "nmb", "delta_cost", "delta_effect")
  )

  impact_mode <- match.arg(
    impact_mode,
    c("absolute", "relative")
  )

  mode <- match.arg(
    mode,
    c("Overall", "Subgroups")
  )

  allowed_facets <- c(
    "none", "dataset", "comparison", "pair",
    "subgroup", "subgroup_var", "subgroup_level"
  )

  allowed_plot_by <- c(
    "none", "dataset", "comparison", "pair",
    "subgroup_var", "subgroup_level"
  )

  validate_directive <- function(value, allowed, argument) {

    if (is.null(value)) {
      return(invisible(TRUE))
    }

    if (!is.character(value) ||
        length(value) != 1L ||
        is.na(value) ||
        !value %in% allowed) {
      stop(
        "'", argument, "' must be one of: ",
        paste(allowed, collapse = ", ")
      )
    }

    invisible(TRUE)
  }

  validate_directive(facet_by, allowed_facets, "facet_by")
  validate_directive(plot_by, allowed_plot_by, "plot_by")

  if (!is.character(facet_scales) ||
      length(facet_scales) != 1L ||
      is.na(facet_scales) ||
      !facet_scales %in% c(
        "fixed", "free", "free_x", "free_y"
      )) {
    stop("Invalid 'facet_scales'.")
  }

  if (!is.logical(show_values) ||
      length(show_values) != 1L ||
      is.na(show_values)) {
    stop("'show_values' must be TRUE or FALSE.")
  }

  if (!is.logical(return_data) ||
      length(return_data) != 1L ||
      is.na(return_data)) {
    stop("'return_data' must be TRUE or FALSE.")
  }

  if (!is.numeric(digits) ||
      length(digits) != 1L ||
      is.na(digits) ||
      !is.finite(digits) ||
      digits < 0 ||
      digits != floor(digits)) {
    stop("'digits' must be a non-negative integer.")
  }

  if (!is.character(palette) ||
      length(palette) != 2L ||
      anyNA(palette)) {
    stop("'palette' must contain two colours.")
  }

  if (!is.character(midpoint_color) ||
      length(midpoint_color) != 1L ||
      is.na(midpoint_color)) {
    stop("'midpoint_color' must be a single colour.")
  }

  if (!is.null(midpoint) &&
      (!is.numeric(midpoint) ||
       length(midpoint) != 1L ||
       !is.finite(midpoint))) {
    stop("'midpoint' must be a finite numeric value.")
  }

  # -------------------------------------------------------------------------
  # 2. Resolve defaults and grid resolution
  # -------------------------------------------------------------------------

  resolved_facet <- facet_by %||%
    if (mode == "Subgroups") "subgroup" else "pair"

  resolved_plot <- plot_by %||% "pair"

  n_levels <- data$settings$n_levels %||% 3L

  if (!is.numeric(n_levels) ||
      length(n_levels) != 1L ||
      is.na(n_levels) ||
      !is.finite(n_levels) ||
      n_levels < 3 ||
      n_levels %% 2 != 1) {
    stop("Invalid TWSA grid resolution.")
  }

  dense_grid <- n_levels > 3L

  # -------------------------------------------------------------------------
  # 3. Resolve metric
  # -------------------------------------------------------------------------

  selected_lambda <- NULL

  if (metric == "nmb") {

    available_lambda <- data$settings$lambda

    if (!is.numeric(available_lambda) ||
        length(available_lambda) == 0L ||
        any(!is.finite(available_lambda))) {
      stop("No valid WTP thresholds available.")
    }

    if (is.null(lambda)) {

      if (length(available_lambda) != 1L) {
        stop(
          "Multiple WTP thresholds available. Specify 'lambda'."
        )
      }

      selected_lambda <- available_lambda

    } else {

      if (!is.numeric(lambda) ||
          length(lambda) != 1L ||
          !is.finite(lambda) ||
          !lambda %in% available_lambda) {
        stop("Selected lambda is not available.")
      }

      selected_lambda <- lambda
    }

    metric_column <- paste0("NMB_", selected_lambda)

  } else {

    metric_column <- metric

    if (!is.null(lambda)) {
      warning(
        "'lambda' is ignored for metric = '",
        metric, "'.",
        call. = FALSE
      )
    }
  }

  # -------------------------------------------------------------------------
  # 4. Extract and filter results
  # -------------------------------------------------------------------------

  df <- data$sensitivity_results

  required <- c(
    "dataset", "subgroup_var", "subgroup_level",
    "comparison", "pair_uid",
    "parameter_1", "parameter_2",
    "scenario_1", "scenario_2",
    "value_1", "value_2", metric_column
  )

  missing <- setdiff(required, names(df))

  if (length(missing) > 0L) {
    stop(
      "Missing TWSA result columns: ",
      paste(missing, collapse = ", ")
    )
  }

  if (!is.null(filter_expr)) {

    if (!is.character(filter_expr) ||
        length(filter_expr) != 1L ||
        is.na(filter_expr) ||
        !nzchar(filter_expr)) {
      stop("'filter_expr' must be a non-empty string.")
    }

    df <- dplyr::filter(
      df,
      !!rlang::parse_expr(filter_expr)
    )
  }

  if (mode == "Overall") {

    df <- df[
      df$subgroup_var == "Overall" |
        is.na(df$subgroup_var),
      ,
      drop = FALSE
    ]

  } else {

    df <- df[
      df$subgroup_var != "Overall" &
        !is.na(df$subgroup_var),
      ,
      drop = FALSE
    ]
  }

  if (nrow(df) == 0L) {
    stop("No results available after filtering.")
  }

  # -------------------------------------------------------------------------
  # 5. Prepare graphical dimensions
  # -------------------------------------------------------------------------

  df$pair <- paste(
    df$parameter_1,
    "vs",
    df$parameter_2
  )

  df$subgroup <- paste(
    df$subgroup_var,
    df$subgroup_level,
    sep = ": "
  )

  if (!is.numeric(df$value_1) ||
      !is.numeric(df$value_2) ||
      any(!is.finite(df$value_1)) ||
      any(!is.finite(df$value_2))) {
    stop("Invalid numerical TWSA parameter values.")
  }

  if (anyNA(df$scenario_1) ||
      anyNA(df$scenario_2)) {
    stop("Invalid TWSA scenario identifiers.")
  }

  # -------------------------------------------------------------------------
  # 6. Resolve absolute or relative impact
  # -------------------------------------------------------------------------

  df$original_value <- df[[metric_column]]

  baseline_keys <- c(
    "dataset",
    "subgroup_var",
    "subgroup_level",
    "comparison",
    "pair_uid"
  )

  baseline_rows <- df[
    df$scenario_1 == "baseline" &
      df$scenario_2 == "baseline",
    c(baseline_keys, "original_value"),
    drop = FALSE
  ]

  names(baseline_rows)[
    names(baseline_rows) == "original_value"
  ] <- "baseline_value"

  if (anyDuplicated(baseline_rows[baseline_keys])) {
    stop("Duplicated TWSA baseline combinations.")
  }

  if (nrow(baseline_rows) == 0L) {
    stop("No baseline-baseline combinations available.")
  }

  # Match analytical baselines without altering row order.

  make_key <- function(x, columns) {

    do.call(
      interaction,
      c(
        lapply(
          x[columns],
          function(z) {
            z <- as.character(z)
            z[is.na(z)] <- "<NA>"
            z
          }
        ),
        list(
          drop = TRUE,
          lex.order = TRUE
        )
      )
    )
  }

  baseline_index <- match(
    as.character(make_key(df, baseline_keys)),
    as.character(make_key(baseline_rows, baseline_keys))
  )

  if (anyNA(baseline_index)) {
    stop(
      "Missing baseline for one or more analytical combinations."
    )
  }

  df$baseline_value <-
    baseline_rows$baseline_value[baseline_index]

  if (impact_mode == "relative") {

    df$plot_value <-
      df$original_value - df$baseline_value

  } else {

    df$plot_value <- df$original_value
  }

  # -------------------------------------------------------------------------
  # 7. Prepare scenario axes and labels
  # -------------------------------------------------------------------------

  if (!dense_grid) {

    scenario_levels <- c(
      "lower", "baseline", "upper"
    )

    if (!all(df$scenario_1 %in% scenario_levels) ||
        !all(df$scenario_2 %in% scenario_levels)) {
      stop("Invalid TWSA scenario identifiers.")
    }

    df$scenario_1 <- factor(
      df$scenario_1,
      levels = scenario_levels,
      labels = c("Lower", "Baseline", "Upper")
    )

    df$scenario_2 <- factor(
      df$scenario_2,
      levels = scenario_levels,
      labels = c("Lower", "Baseline", "Upper")
    )
  }

  df$value_label <- ifelse(
    is.finite(df$plot_value),
    formatC(
      df$plot_value,
      format = "f",
      digits = digits,
      big.mark = ","
    ),
    "NA"
  )

  # -------------------------------------------------------------------------
  # 8. Validate analytical combinations
  # -------------------------------------------------------------------------

  keys <- c(
    "dataset", "subgroup_var", "subgroup_level",
    "comparison", "pair_uid",
    "scenario_1", "scenario_2"
  )

  if (anyDuplicated(df[keys])) {
    stop("Duplicated TWSA scenario combinations.")
  }

  # -------------------------------------------------------------------------
  # 9. Return prepared data if requested
  # -------------------------------------------------------------------------

  if (return_data && resolved_plot == "none") {
    return(df)
  }

  # -------------------------------------------------------------------------
  # 10. Metric labels
  # -------------------------------------------------------------------------

  metric_label <- switch(
    metric,
    nmb = paste0(
      "Incremental NMB (WTP = ",
      format(
        selected_lambda,
        big.mark = ",",
        scientific = FALSE,
        trim = TRUE
      ),
      ")"
    ),
    icer = "Incremental cost-effectiveness ratio",
    delta_cost = "Incremental cost",
    delta_effect = "Incremental effectiveness"
  )

  plotted_metric_label <- if (impact_mode == "relative") {
    paste0("Change from baseline in ", metric_label)
  } else {
    metric_label
  }

  legend_label <- switch(
    metric,
    nmb = "NMB",
    icer = "ICER",
    delta_cost = "\u0394 Cost",
    delta_effect = "\u0394 Effect"
  )

  # -------------------------------------------------------------------------
  # 11. Internal function: validate numerical panel compatibility
  # -------------------------------------------------------------------------

  validate_panel_axes <- function(plot_df) {

    if (!dense_grid) {
      return(invisible(TRUE))
    }

    panel_keys <- switch(
      resolved_facet,
      none = character(0),
      subgroup = c("subgroup_var", "subgroup_level"),
      resolved_facet
    )

    # A panel must contain one ordered pair of parameter identities.
    # Identical numeric ranges alone are not sufficient.

    panel_groups <- if (length(panel_keys) == 0L) {

      list(plot_df)

    } else {

      panel_id <- make_key(plot_df, panel_keys)
      split(plot_df, panel_id, drop = TRUE)
    }

    for (panel_df in panel_groups) {

      axis_pairs <- unique(
        panel_df[c("parameter_1", "parameter_2")]
      )

      if (nrow(axis_pairs) > 1L) {

        stop(
          "Incompatible parameter axes within a plotting panel. ",
          "Each numerical heatmap panel must represent one ",
          "ordered parameter pair. ",
          "Use plot_by = 'pair' or facet_by = 'pair' ",
          "to separate parameter pairs.",
          call. = FALSE
        )
      }
    }

    invisible(TRUE)
  }

  # -------------------------------------------------------------------------
  # 12. Internal function: build one heatmap
  # -------------------------------------------------------------------------

  build_plot <- function(plot_df, plot_label = NULL) {

    validate_panel_axes(plot_df)

    base <- ce_plot_base(
      data = plot_df,
      color_by = "none",
      shape_by = "none",
      facet_by = "none",
      plot_by = "none",
      palette = palette
    )

    plot_df <- base$data

    unique_pairs <- unique(plot_df$pair_uid)

    if (length(unique_pairs) == 1L) {

      x_label <- unique(plot_df$parameter_1)[1]
      y_label <- unique(plot_df$parameter_2)[1]

    } else {

      x_label <- "Parameter 1"
      y_label <- "Parameter 2"
    }

    # -----------------------------------------------------------------------
    # Heatmap geometry
    # -----------------------------------------------------------------------

    if (!dense_grid) {

      p <- ggplot2::ggplot(
        plot_df,
        ggplot2::aes(
          x = scenario_1,
          y = scenario_2,
          fill = plot_value
        )
      ) +
        ggplot2::geom_tile(
          colour = "white",
          linewidth = 0.8
        ) +
        ggplot2::coord_equal()

    } else {

      compute_boundaries <- function(values) {

        values <- sort(unique(values))

        if (length(values) < 2L) {
          stop(
            "At least two distinct parameter values are required ",
            "for a numerical heatmap."
          )
        }

        if (any(diff(values) <= 0)) {
          stop("Parameter values must be strictly increasing.")
        }

        midpoints <- (
          values[-1L] +
            values[-length(values)]
        ) / 2

        lower_bounds <- c(
          values[1L],
          midpoints
        )

        upper_bounds <- c(
          midpoints,
          values[length(values)]
        )

        data.frame(
          value = values,
          lower = lower_bounds,
          upper = upper_bounds
        )
      }

      # Compute boundaries separately for each analytical series.
      # This avoids mixing parameter levels from different datasets,
      # comparisons or subgroups.

      grid_keys <- c(
        "dataset",
        "subgroup_var",
        "subgroup_level",
        "comparison",
        "pair_uid"
      )

      grid_id <- make_key(plot_df, grid_keys)

      plot_parts <- lapply(
        split(plot_df, grid_id, drop = TRUE),
        function(pair_df) {

          x_bounds <- compute_boundaries(
            pair_df$value_1
          )

          y_bounds <- compute_boundaries(
            pair_df$value_2
          )

          x_index <- match(
            pair_df$value_1,
            x_bounds$value
          )

          y_index <- match(
            pair_df$value_2,
            y_bounds$value
          )

          pair_df$xmin <- x_bounds$lower[x_index]
          pair_df$xmax <- x_bounds$upper[x_index]

          pair_df$ymin <- y_bounds$lower[y_index]
          pair_df$ymax <- y_bounds$upper[y_index]

          pair_df
        }
      )

      plot_df <- dplyr::bind_rows(plot_parts)

      p <- ggplot2::ggplot(
        plot_df,
        ggplot2::aes(
          xmin = xmin,
          xmax = xmax,
          ymin = ymin,
          ymax = ymax,
          fill = plot_value
        )
      ) +
        ggplot2::geom_rect(
          colour = "white",
          linewidth = 0.15
        ) +
        ggplot2::scale_x_continuous(
          expand = ggplot2::expansion(mult = 0)
        ) +
        ggplot2::scale_y_continuous(
          expand = ggplot2::expansion(mult = 0)
        ) +
        ggplot2::coord_cartesian()
    }

    # -----------------------------------------------------------------------
    # Shared theme
    # -----------------------------------------------------------------------

    p <- p +
      ggplot2::theme_bw() +
      ggplot2::theme(
        panel.grid.major = ggplot2::element_blank(),
        panel.grid.minor = ggplot2::element_blank(),
        strip.background = ggplot2::element_rect(
          fill = "grey90",
          colour = NA
        ),
        strip.text = ggplot2::element_text(
          face = "bold"
        )
      )

    # -----------------------------------------------------------------------
    # Colour scale
    # -----------------------------------------------------------------------

    if (is.null(midpoint)) {

      p <- p +
        ggplot2::scale_fill_gradient(
          low = unname(palette[1]),
          high = unname(palette[2]),
          na.value = "grey85"
        )

    } else {

      p <- p +
        ggplot2::scale_fill_gradient2(
          low = unname(palette[1]),
          mid = midpoint_color,
          high = unname(palette[2]),
          midpoint = midpoint,
          na.value = "grey85"
        )
    }

    # -----------------------------------------------------------------------
    # Cell labels
    # -----------------------------------------------------------------------

    if (show_values) {

      if (!dense_grid) {

        p <- p +
          ggplot2::geom_text(
            ggplot2::aes(label = value_label),
            size = 3.4
          )

      } else {

        p <- p +
          ggplot2::geom_text(
            data = plot_df,
            mapping = ggplot2::aes(
              x = value_1,
              y = value_2,
              label = value_label
            ),
            inherit.aes = FALSE,
            size = 2.5
          )
      }
    }

    # -----------------------------------------------------------------------
    # Faceting
    # -----------------------------------------------------------------------

    if (resolved_facet == "subgroup") {

      p <- p +
        ggplot2::facet_grid(
          rows = ggplot2::vars(subgroup_level),
          cols = ggplot2::vars(subgroup_var),
          scales = facet_scales
        )

    } else if (resolved_facet != "none") {

      p <- p +
        ggplot2::facet_wrap(
          ggplot2::vars(
            !!rlang::sym(resolved_facet)
          ),
          scales = facet_scales
        )
    }

    # -----------------------------------------------------------------------
    # Titles and labels
    # -----------------------------------------------------------------------

    subtitle <- plotted_metric_label

    if (!is.null(plot_label)) {

      subtitle <- paste0(
        subtitle,
        " | ",
        resolved_plot,
        ": ",
        plot_label
      )
    }

    p <- p +
      ggplot2::labs(
        title = "Two-Way Sensitivity Analysis",
        subtitle = subtitle,
        x = x_label,
        y = y_label,
        fill = legend_label
      )

    return(p)
  }

  # -------------------------------------------------------------------------
  # 13. Combined plot
  # -------------------------------------------------------------------------

  if (resolved_plot == "none") {

    return(
      build_plot(df)
    )
  }

  # -------------------------------------------------------------------------
  # 14. Independent plots
  # -------------------------------------------------------------------------

  plot_levels <- sort(
    unique(as.character(df[[resolved_plot]]))
  )

  output <- vector(
    "list",
    length(plot_levels)
  )

  names(output) <- plot_levels

  for (level in plot_levels) {

    plot_df <- df[
      as.character(df[[resolved_plot]]) == level,
      ,
      drop = FALSE
    ]

    if (return_data) {

      output[[level]] <- plot_df

    } else {

      output[[level]] <- build_plot(
        plot_df,
        plot_label = level
      )
    }
  }

  # -------------------------------------------------------------------------
  # 15. Shared multiple-plots handler
  # -------------------------------------------------------------------------

  if (!return_data) {

    output <- cea_multplots_handler(
      output,
      plot_type = "TWSA heatmap"
    )
  }

  return(output)
}
